{
  "name": "Newport Picomotor精密位移台",
  "name_en": "Newport Picomotor Precision Stage",
  "manufacturer": "Newport",
  "description": "一种由 Newport Picomotor 微型执行器驱动的多轴精密位移台，用于对光学元件、样品或探针进行高分辨率微调定位。常见于光学对准、光纤耦合、显微实验和精密机械定位等实验场景。",
  "description_en": "A multi-axis precision positioning stage driven by Newport Picomotor actuators, used for fine high-resolution adjustment of optical components, samples, or probes. It is commonly used in optical alignment, fiber coupling, microscopy, and other precision positioning tasks in the lab.",
  "tag_hints": [
    "picomotor positioning",
    "optical alignment",
    "multi-axis stage",
    "precision translation",
    "nanopositioning",
    "fiber coupling"
  ],
  "actions": [
    {
      "action_name": "auto-get_product_id",
      "description": "获取设备产品标识。",
      "description_en": "Get the device product ID."
    },
    {
      "action_name": "auto-wait_scan_done",
      "description": "等待控制器扫描完成。",
      "description_en": "Wait for the controller scan to complete."
    },
    {
      "action_name": "auto-resolve_address_conflicts",
      "description": "解决控制器地址冲突。",
      "description_en": "Resolve controller address conflicts."
    },
    {
      "action_name": "auto-get_controllers_scan",
      "description": "获取扫描发现的控制器列表。",
      "description_en": "Get the list of controllers found by scanning."
    },
    {
      "action_name": "auto-wait_motor_moved",
      "description": "等待电机运动完成。",
      "description_en": "Wait for motor motion to complete."
    },
    {
      "action_name": "auto-get_home_position",
      "description": "获取回零参考位置。",
      "description_en": "Get the home position."
    },
    {
      "action_name": "auto-set_home_position",
      "description": "设置回零参考位置。",
      "description_en": "Set the home position."
    }
  ]
}

